/* Just for fun, above is a more interesting configuration for the cells.
 * You can mostly copy your code from warmup.cpp here to try it out.  Note
 * the changes suggested below (using sleep to animate). */
int main()
{
	/* to draw some nicer, animated pictures, proceed as follows: */
	while (true) {
		/* print the current state of the world (and maybe use spaces instead of '.') */
		/* allocate some scratch space to figure out what will happen next: */
		vector<vector<bool>> future(world); /* NOTE: copying world just gets the dimensions right.
		                                       We didn't actually need to copy the values. */
		/* apply rules, writing result to future */
		/* ...your code goes here... */
		/* now that the future is computed, overwrite world, and then sleep */
		world = future;
		sleep(1);
	}
	return 0;
}
